import { useContext } from "solid-js";

// src/FirebaseProvider.tsx
import { createContext } from "solid-js";
var FirebaseContext = createContext();
var FirebaseProvider = (props) => {
  return (
    // eslint-disable-next-line solid/reactivity
    <FirebaseContext.Provider value={props.app}>{props.children}</FirebaseContext.Provider>
  );
};

// src/hooks/useFirebaseApp.tsx
function useFirebaseApp() {
  const app = useContext(FirebaseContext);
  if (!app) {
    throw new Error(
      "useFirebaseApp must be used within a <FirebaseContext.Provider />"
    );
  }
  return app;
}

