import { createStore as createStore2, reconcile as reconcile2 } from "solid-js/store";

// src/utils.ts
function isDocumentReference(docRef) {
  return (docRef.path?.match(/\//g) || []).length % 2 !== 0;
}
function isDefined(val) {
  return typeof val !== "undefined";
}
function access(v) {
  return typeof v === "function" && !v.length ? v() : v;
}
